def solve(nums, k):
    var1 = []
    for num in nums:
        if len(var1) < k:
            # Maintain a max-heap of size k
            if not var1 or num > -var1[0]:
                if var1:
                    val = -heapq.heappop(var1)
                    if val > num:
                        num = val
                var1.append(-num)
                if len(var1) > k:
                    val = -heapq.heappop(var1)
                    var1.append(-val)
        else:
            # Replace the max element if current num is smaller
            if num < -var1[0]:
                val = -heapq.heappop(var1)
                if val > num:
                    num = val
                var1.append(-num)
                if len(var1) > k:
                    val = -heapq.heappop(var1)
                    var1.append(-val)
    return -var1[0]
